function wpbp_theme_templates_002( string $template_slug ): string {
    $hierarchy = get_template_hierarchy( $template_slug );
    $available = wp_list_pluck( get_block_templates(), 'slug' );
    foreach ( $hierarchy as $candidate ) {
        if ( in_array( $candidate, $available, true ) ) {
            return $candidate;
        }
    }
    return 'index';
}

function wpbp_theme_templates_003( string $template_slug ): array {
    $template = get_block_template( get_stylesheet() . '//' . $template_slug, 'wp_template' );
    if ( ! $template instanceof WP_Block_Template ) {
        return array( 'source' => '', 'content' => '' );
    }
    return array( 'source' => (string) $template->source, 'content' => (string) $template->content );
}

