add_filter( 'nav_menu_link_attributes', static function ( $atts, $menu_item, $args, $depth ) {
    $url = $menu_item->url ?? '';
    if ( '' === $url ) {
        return $atts;
    }
    $host = wp_parse_url( $url, PHP_URL_HOST );
    if ( ! $host || $host === wp_parse_url( home_url(), PHP_URL_HOST ) ) {
        return $atts;
    }
    $atts['target'] = '_blank';
    $rel            = trim( (string) ( $atts['rel'] ?? '' ) );
    $atts['rel']    = trim( $rel . ' noopener nofollow' );
    return $atts;
}, 10, 4 );

