add_filter( 'the_content', static function ( $content ) {
    $blocks  = parse_blocks( $content );
    $indices = array();
    foreach ( $blocks as $index => $block ) {
        if ( ! empty( $block['blockName'] ) ) {
            $indices[] = $index;
        }
    }
    if ( count( $indices ) <= 2 ) {
        return $content;
    }
    $promo = parse_blocks( '<!-- wp:paragraph {"className":"wpbp-promo"} --><p class="wpbp-promo">Sponsored by WPBP</p><!-- /wp:paragraph -->' );
    array_splice( $blocks, $indices[1] + 1, 0, $promo );
    return serialize_blocks( $blocks );
}, 8 );

class WPBP_Recent_Items_Widget extends WP_Widget {
    public function __construct() {
        parent::__construct( 'wpbp-recent-items', 'WPBP Recent Items', array( 'classname' => 'wpbp-recent-items', 'description' => 'Recent entries.' ) );
    }

    public function widget( $args, $instance ) {
        $number    = isset( $instance['number'] ) ? (int) $instance['number'] : 3;
        $post_type = isset( $instance['post_type'] ) ? (string) $instance['post_type'] : 'post';
        if ( $number < 1 ) {
            $number = 3;
        }
        $query = new WP_Query(
            array(
                'post_type'           => $post_type,
                'post_status'         => 'publish',
                'posts_per_page'      => $number,
                'ignore_sticky_posts' => true,
                'no_found_rows'       => true,
            )
        );
        if ( ! $query->have_posts() ) {
            return;
        }
        echo $args['before_widget'];
        $title = apply_filters( 'widget_title', $instance['title'] ?? '', $instance, $this->id_base );
        if ( '' !== trim( (string) $title ) ) {
            echo $args['before_title'] . esc_html( $title ) . $args['after_title'];
        }
        echo '<ul class="wpbp-recent-items-list">';
        foreach ( $query->posts as $post ) {
            printf( '<li><a href="%s">%s</a></li>', esc_url( (string) get_permalink( $post ) ), esc_html( get_the_title( $post ) ) );
        }
        echo '</ul>';
        echo $args['after_widget'];
    }
}

register_widget( 'WPBP_Recent_Items_Widget' );
add_action( 'widgets_init', static function () { register_widget( 'WPBP_Recent_Items_Widget' ); } );
